insert into public.atlas_sources (id, title, publisher, url, note) values
  ('worldpop-2020-agesex', 'Age and sex structures, Kenya, 2020, 100 m grid', 'WorldPop (University of Southampton)', 'https://hub.worldpop.org/geodata/listing?id=65', 'Estimates, summed inside each ward''s boundary through WorldPop''s statistics API (dataset wpgpas); 18–34 counts two fifths of the 15–19 band.'),
  ('iebc-2022-form-34c', 'Declaration of results for the election of President, national tallying centre, by county (Form 34C summary), 2022', 'IEBC', 'https://www.iebc.or.ke/uploads/resources/QLTlLJx0Vr.pdf', 'County and national totals as printed. Votes cast is valid plus rejected. The national valid total (14,213,137) is 110 more than the four candidates'' votes added up (14,213,027), as printed.'),
  ('electionskenya-2013-president', '2013 presidential results by county', 'electionskenya.org', 'http://www.electionskenya.org/results/PR/2013/', 'A third-party election observation site; its 2013 national totals match IEBC''s declaration. County rows list only the four leading candidates and no votes cast. Parties and coalitions come from the candidates'' widely reported 2013 tickets'),
  ('electionskenya-2022-register', 'Registered voters per county assembly ward, 2022', 'electionskenya.org', 'http://www.electionskenya.org/county/047/', 'Ward pages of a third-party site carrying IEBC''s 2022 register. Nairobi''s wards add up to 2,415,310 against IEBC''s declared 2,416,551. Mugumo-ini is spelt Mugumu-ini there.'),
  ('electionskenya-2022-candidates', '2022 candidates and registered voters by constituency', 'electionskenya.org', 'http://www.electionskenya.org/constituency/274/', 'Constituency pages of a third-party site carrying IEBC''s 2022 candidate list (official names and parties) and register; names are given here as other names then surname. Its county pages give the 2022 governor candidates; both lists are what the provisional results were checked against for completeness.'),
  ('star-2022-nairobi-governor', 'Sakaja declared winner in Nairobi governor race', 'The Star', 'https://www.the-star.co.ke/counties/central/2022-08-14-sakaja-declared-winner-in-nairobi-governor-race', 'Sakaja''s and Igathe''s votes in each constituency, as printed (the top two only). Its county-wide figures (699,392 and 573,518) were checked against the provisional results, which list every candidate and are loaded for the county instead. Three rows labelled only ''Embakasi'' can''t be placed and Embakasi South''s Igathe figure is misprinted (''3,7647''), so the four Embakasi North, Central, East and South rows are left out.'),
  ('star-2022-westlands-mp', 'Wanyonyi retains Westlands MP seat', 'The Star', 'https://www.the-star.co.ke/news/2022-08-12-wanyonyi-retains-westlands-mp-seat', 'The top two, as printed. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('citizen-2022-kibra-mp', 'Imran Okoth loses Kibra MP seat as Peter Orero is declared winner', 'Citizen Digital', 'https://citizen.digital/news/imran-okoth-loses-kibra-mp-seat-as-peter-orero-is-declared-winner-n303779', 'The top three, as printed; Capital FM printed the same figures. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('citizen-2022-langata-mp', 'Comedian Jalang''o wins Lang''ata MP seat', 'Citizen Digital', 'https://citizen.digital/article/comedian-jalango-wins-langata-mp-seat-n303793', 'The top two, as printed. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('citizen-2022-embakasi-east-mp', 'Babu Owino retains Embakasi East MP seat', 'Citizen Digital', 'https://citizen.digital/article/babu-owino-retains-embakasi-east-mp-seat-n303795', 'The top two at the declaration. The Star''s round-up of 11 August printed 65,540 and 34,450 from an unfinished count.'),
  ('star-2022-embakasi-central-mp', 'Benjamin Gathiru re-elected as Embakasi Central MP', 'The Star', 'https://www.the-star.co.ke/news/2022-08-11-benjamin-gathiru-re-elected-as-embakasi-central-mp', 'The top two, as printed. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('star-2022-mathare-mp', 'Bahati floored in hotly contested Mathare MP race', 'The Star', 'https://www.the-star.co.ke/news/2022-08-12-bahati-floored-in-hotly-contested-mathare-mp-race/', 'The top three, as printed. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('citizen-2022-kasarani-mp', 'SportPesa CEO Ronald Karauri declared Kasarani MP-elect', 'Citizen Digital', 'https://citizen.digital/article/sportpesa-ceo-ronald-karauri-declared-kasarani-mp-elect-n303778', 'The top three, as printed; it names the runner-up John Kamau, but the official candidate list and The Star name UDA''s John Njoroge Chege with the same 30,444 votes.'),
  ('citizen-2022-dagoretti-north-mp', 'Beatrice Elachi wins Dagoretti North MP race', 'Citizen Digital', 'https://citizen.digital/article/beatrice-elachi-wins-dagoretti-north-mp-race-n303832', 'The top two, as printed. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('citizen-2022-dagoretti-south-mp', 'John ''KJ'' Kiarie retains Dagoretti South MP seat', 'Citizen Digital', 'https://citizen.digital/article/john-kj-kiarie-retains-dagoretti-south-mp-seat-n303794', 'The top two, as printed. Checked against the provisional results loaded instead, which list every candidate; the leaders'' figures agree.'),
  ('star-2022-starehe-mp', 'Jubilee''s Amos Mwago elected as Starehe MP', 'The Star', 'https://www.the-star.co.ke/news/2022-08-12-jubilees-amos-mwago-elected-as-starehe-mp', 'The top two, as printed. Checked against the provisional results loaded instead, which list every candidate; they give the winner 50,777 where this printed 50,787.'),
  ('star-2022-roysambu-president', 'Roysambu embraces Ruto, gives him big win in presidential poll', 'The Star', 'https://www.the-star.co.ke/news/2022-08-14-roysambu-embraces-ruto-gives-him-big-win-in-presidential-poll', 'Ruto''s and Odinga''s votes, registered, valid and rejected as printed; votes cast is valid plus rejected.'),
  ('star-2022-embakasi-west-history', 'MP Theuri accepts defeat in Embakasi West race', 'The Star', 'https://www.the-star.co.ke/news/2022-08-10-theuri-accepts-defeat-in-embakasi-west-race', 'Theuri''s 2013 win, the top two; his 2013 party (TNA) is from his widely reported ticket. Its 2017 figures (47,848 to 30,983) differ from the provisional results'' (55,819 to 35,358), which are loaded.'),
  ('star-2022-nairobi-roundup', 'Ruto''s soldiers lose as Azimio paints city blue', 'The Star', 'https://www.the-star.co.ke/counties/nairobi/2022-08-11-rutos-soldiers-lose-as-azimio-paints-city-blue/', 'Nairobi''s 2017 presidential result, the top two (the 8 August vote).'),
  ('provisional-2022-mp-nairobi', '2022 Member of National Assembly results, Nairobi City', 'Provisional results', null, 'Public provisional figures for each constituency, every candidate, not yet checked against IEBC''s Forms 35B. Loaded where the list matches IEBC''s candidate list in full, with valid as the candidates'' total, and for Dagoretti North and South, where one minor candidate is missing, without a valid total. Not loaded for Kasarani (3 of 14 candidates, the runner-up under another party than the press and IEBC''s list give), Ruaraka (3 of 9, without UDA''s) or Embakasi East (2 of 5); Embakasi North had no figures. On the leaders they agree with The Star, Citizen Digital and The Standard in nine seats; they give Roysambu''s runner-up 40,381 where the Daily Nation printed 40,140.'),
  ('provisional-2017-mp-nairobi', '2017 Member of National Assembly results, Nairobi City', 'Provisional results', null, 'Public provisional figures for each constituency, names as printed (surname first), not yet checked against IEBC''s forms. Whether every candidate is listed isn''t checked, so shares are of the candidates listed. They give Ruaraka''s runner-up 31,512 where the Daily Nation printed 21,512, and Makadara 45,516 to 41,125 where the Nation''s provisional count was 41,874 to 39,731.'),
  ('provisional-2022-governor-nairobi', '2022 Governor result, Nairobi City County', 'Provisional results', null, 'Public provisional figures for the county, all nine candidates on IEBC''s list, not yet checked against IEBC''s Form 37C; valid is their total. They give Igathe 573,516 where The Star printed 573,518.'),
  ('provisional-2017-governor-nairobi', '2017 Governor result, Nairobi City County', 'Provisional results', null, 'Public provisional figures for the county, eight candidates, names as printed, not yet checked against IEBC''s forms. Whether every candidate is listed isn''t checked, so shares are of the candidates listed.'),
  ('star-2022-mathira-president', 'Mathira gives Ruto massive win over Raila', 'The Star', 'https://www.the-star.co.ke/news/2022-08-14-mathira-gives-ruto-massive-win-over-raila', 'Mathira''s presidential result as printed. Its ''votes cast'' (73,439) equals the four candidates'' votes added up, so it is probably the valid total; entered as printed.'),
  ('kna-2022-nyeri-mps', 'Political newcomers dominate Nyeri MP seats', 'Kenya News Agency', 'https://www.kenyanews.go.ke/political-newcomers-dominate-nyeri-mp-seats/1000/', 'The government news agency''s report of five of Nyeri''s six MP races, the leading candidates as printed. Its ''58,534 votes cast'' in Mukurweini is that constituency''s register, so it isn''t entered as votes cast; Othaya''s ''44,676 votes'' is entered as votes cast.'),
  ('provisional-2022-mp-nyeri', '2022 Member of National Assembly results, Nyeri', 'Provisional results', null, 'Loaded for Tetu only: public provisional figures whose nine candidates match IEBC''s list and add up to 38,066, which fits the Kenya News Agency''s 38,314 votes cast; not yet checked against IEBC''s Form 35B. Not loaded for Othaya, where the list lacks the Jubilee incumbent and gives Chama Cha Kazi''s candidate 523 where the agency printed 7,152.'),
  ('provisional-2017-mp-nyeri', '2017 Member of National Assembly results, Nyeri', 'Provisional results', null, 'Public provisional figures for each constituency, names as printed (surname first), not yet checked against IEBC''s forms. Whether every candidate is listed isn''t checked, so shares are of the candidates listed. Mathira''s leaders agree with IEBC''s figures as Citizen Digital reported them.'),
  ('provisional-2022-governor-nyeri', '2022 Governor result, Nyeri County', 'Provisional results', null, 'Public provisional figures for the county, all four candidates on IEBC''s list, names as printed (titles included, as on IEBC''s list), not yet checked against IEBC''s Form 37C; valid is their total.'),
  ('provisional-2017-governor-nyeri', '2017 Governor result, Nyeri County', 'Provisional results', null, 'Public provisional figures for the county, three candidates, names as printed, not yet checked against IEBC''s forms. Whether every candidate is listed isn''t checked, so shares are of the candidates listed.')
